//! Factorized LMR term — GENERATED by tools/scripts/gen_factorized_lmr.py, do not edit.
//!
//! The reduction's context is 9 booleans. Rather than one weight per cell of
//! the full table (2^9 cells, each trained only by the nodes that hit it
//! exactly), this keeps one weight per subset of inputs up to order 3 —
//! main effects, pairs, triples — and sums the weights of every subset the
//! context satisfies. Every node feeds every term it satisfies, so a rare
//! context still learns from the common ones it shares terms with. Subsets made
//! impossible or redundant by the constraints below carry no weight.
//!
//! Constraints: pv -> ttpv, pv -> !cutnode, cutnode -> !pv, root -> pv.
//! 96 canonical terms (one intercept, 9 main effects, the rest
//! pairs and triples), in 1/1024 ply; positive reduces more.

use crate::tune;

pub const PV: usize = 1 << 0;
pub const CUTNODE: usize = 1 << 1;
pub const IMPROVING: usize = 1 << 2;
pub const TTMOVE: usize = 1 << 3;
pub const TTPV: usize = 1 << 4;
pub const QUIET: usize = 1 << 5;
pub const GIVESCHECK: usize = 1 << 6;
pub const ROOT: usize = 1 << 7;
pub const FH2: usize = 1 << 8;

/// Number of context bits.
pub const BITS: usize = 9;

/// Pack the context into the table index. Bit order is fixed by the generator.
#[inline(always)]
pub fn context_mask(
    pv: bool,
    cutnode: bool,
    improving: bool,
    ttmove: bool,
    ttpv: bool,
    quiet: bool,
    givescheck: bool,
    root: bool,
    fh2: bool,
) -> usize {
    debug_assert!(!(pv && !ttpv), "factorized LMR: pv -> ttpv violated");
    debug_assert!(!(pv && cutnode), "factorized LMR: pv -> !cutnode violated");
    debug_assert!(!(cutnode && pv), "factorized LMR: cutnode -> !pv violated");
    debug_assert!(!(root && !pv), "factorized LMR: root -> pv violated");
    ((pv as usize) << 0)
        | ((cutnode as usize) << 1)
        | ((improving as usize) << 2)
        | ((ttmove as usize) << 3)
        | ((ttpv as usize) << 4)
        | ((quiet as usize) << 5)
        | ((givescheck as usize) << 6)
        | ((root as usize) << 7)
        | ((fh2 as usize) << 8)
}

